import Flutter
import UIKit
import XCTest

@testable import Runner

/// CommonCrypto PBKDF2 must give exactly the bytes of the app's Dart
/// implementation. The vectors below are generated by Python's hashlib
/// (tool/gen_pbkdf2_vectors.py) and are the same ones the Dart and Kotlin
/// tests check.
class RunnerTests: XCTestCase {

  func testEveryVectorMatches() throws {
    for vector in RunnerTests.vectors {
      let derived = try Pbkdf2Native.derive(
        password: RunnerTests.bytes(vector.password),
        salt: RunnerTests.bytes(vector.salt),
        iterations: vector.iterations,
        length: 32)
      XCTAssertEqual(RunnerTests.hex(derived), vector.derived, vector.name)
    }
  }

  func testOutOfRangeInputIsRefused() {
    let salt = [UInt8](repeating: 1, count: 16)
    XCTAssertThrowsError(try Pbkdf2Native.derive(password: [1], salt: salt, iterations: 0, length: 32))
    XCTAssertThrowsError(
      try Pbkdf2Native.derive(password: [1], salt: salt, iterations: 10_000_001, length: 32))
    XCTAssertThrowsError(try Pbkdf2Native.derive(password: [1], salt: [], iterations: 1, length: 32))
    XCTAssertThrowsError(
      try Pbkdf2Native.derive(
        password: [UInt8](repeating: 1, count: 1025), salt: salt, iterations: 1, length: 32))
  }

  func testFiveRunsAt210000ArePrinted() throws {
    // Not a pass/fail gate: the simulator says nothing about phone speed.
    let salt = [UInt8](repeating: 7, count: 16)
    let start = Date()
    _ = try Pbkdf2Native.derive(password: Array("correct horse 1".utf8), salt: salt, iterations: 210_000, length: 32)
    print("CommonCrypto PBKDF2 210000: \(Int(Date().timeIntervalSince(start) * 1000)) ms")
  }

  static func bytes(_ hex: String) -> [UInt8] {
    var out = [UInt8]()
    var index = hex.startIndex
    while index < hex.endIndex {
      let next = hex.index(index, offsetBy: 2)
      out.append(UInt8(hex[index..<next], radix: 16)!)
      index = next
    }
    return out
  }

  static func hex(_ bytes: [UInt8]) -> String {
    bytes.map { String(format: "%02x", $0) }.joined()
  }

